package com.agrolink.service.impl; import com.agrolink.dto.category.*;import com.agrolink.entity.Category;import com.agrolink.repository.CategoryRepository;import com.agrolink.service.CategoryService;import org.springframework.stereotype.Service;import java.util.*;@Service public class CategoryServiceImpl implements CategoryService{private final CategoryRepository r;public CategoryServiceImpl(CategoryRepository r){this.r=r;}public CategoryResponse create(CategoryRequest x){if(r.existsByNameIgnoreCase(x.name()))throw new RuntimeException("Category already exists");Category c=new Category();c.setName(x.name().trim());c.setDescription(x.description());return to(r.save(c));}public List<CategoryResponse> all(){return r.findAll().stream().map(this::to).toList();}public CategoryResponse update(Long id,CategoryRequest x){Category c=r.findById(id).orElseThrow(()->new RuntimeException("Category not found"));c.setName(x.name().trim());c.setDescription(x.description());return to(r.save(c));}public void delete(Long id){if(!r.existsById(id))throw new RuntimeException("Category not found");r.deleteById(id);}private CategoryResponse to(Category c){return new CategoryResponse(c.getId(),c.getName(),c.getDescription());}}